args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-ape-fig3-synteny');S<-file.path(P,'biofigure')
source(file.path(S,'scripts/figure_style.R'));library(ggplot2)
font<-bf_font('Arial');sp<-file.path(W,'design-spec.yaml');spec<-yaml::read_yaml(sp)
p<-readRDS(file.path(W,'render-object.rds'));F<-file.path(P,'results/figures/ape_fig3ad_synteny_simulated_recolored_20261029')
inputs<-list.files(file.path(P,'results/plot_data'),pattern='^ape_fig3_synteny_simulated_.*20261029.csv$',full.names=TRUE)
lock<-jsonlite::fromJSON(file.path(W,'source-review-receipt.json'))
sources<-unique(c(file.path(W,c('render.R','prepare_plots.R','prepare_grobs.R','prepare_spec.py','source-and-palette.json','render-object.rds','composed-vector-grob.rds','text-manifest.json','source-review-receipt.json')),sp,inputs,lock$source_files$path,file.path(S,c('scripts/figure_style.R','palettes/bright-luts.csv','palettes/continuous-luts.csv'))))
auth<-file.path(W,paste0('authorization-',Sys.getpid(),'.json'))
a<-c(file.path(S,'scripts/authorize_render.py'),'--receipt',file.path(W,'preparation-receipt.json'),'--design-spec',sp,'--output',auth,unlist(lapply(setdiff(sources,sp),function(f)c('--source',f))))
